import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"格式化字符串","description":"","frontmatter":{"title":"格式化字符串","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/format-string.md","filePath":"cs/format-string.md","lastUpdated":1789023840000}'),h={name:"cs/format-string.md"};function E(f,a,u,m,_,B){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="格式化字符串" tabindex="-1">格式化字符串 <a class="header-anchor" href="#格式化字符串" aria-label="Permalink to &quot;格式化字符串&quot;">​</a></h1><div class="epigraph"><p>`printf` 的格式串是微型语言。若把用户输入当成格式，说明符会去读（历史上甚至写）栈上的参数槽。正确合同：格式串是程序员常量。</p><footer>—— 据 CWE-134；对照 Newsham 与其他早期公开分析；ISO C `fprintf` 合同</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/integer-overflow-bugs">整数溢出</a>是算术。缺口是<strong>解释器</strong>：格式化字符串。本课钉「不可把不可信串当格式」，不给 <code>%n</code> 利用步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日志写成 <code>printf(user)</code>。说明符消耗参数，错位则泄栈，危险说明符曾能写内存。缺口是 API 选择：<code>printf(&quot;%s&quot;, user)</code>。编译器 <code>-Wformat-security</code> 抓一部分。</p><h3 id="n-已在许多-libc-弱化" tabindex="-1">%n 已在许多 libc 弱化 <a class="header-anchor" href="#n-已在许多-libc-弱化" aria-label="Permalink to &quot;%n 已在许多 libc 弱化&quot;">​</a></h3><p>即使写功能被关，信息泄漏仍在。合同仍是：格式常量。</p><p><span class="marginnote">CWE-134。本课禁止构造恶意格式串作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照安全与不安全调用。指出日志库应自带格式。类型混淆下一课把「解释错误」升到对象类型层。</p>',12)),(e(),s(p,null,{default:r(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E4%B8%B2%22%5D%20--%3E%20BAD%5B%22%E5%BD%93%E4%BD%9C%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20BAD%20--%3E%20LEAK%5B%22%E8%AF%BB%E9%94%99%E5%8F%82%E6%95%B0%E6%A7%BD%22%5D%0A%20%20CST%5B%22%E5%B8%B8%E9%87%8F%E6%A0%BC%E5%BC%8F%22%5D%20--%3E%20OK%5B%22%E7%94%A8%E6%88%B7%E5%8F%AA%E5%BD%93%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>输入不应选择解释规则。下一课类型混淆：在对象层选错虚表或 union。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无泄漏配方。类型混淆下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长度算错之外，格式串是微型语言。</li><li>不可信数据不得当格式。</li><li>编译器警告是辅助，不是证明。</li><li>下一课类型混淆。</li><li>出处：CWE-134；ISO C；对照 Szekeres SoK。</li></ul>',8))])}const q=i(h,[["render",E]]);export{b as __pageData,q as default};
